requires [capability("capability.invoke")];
let land = capability.invoke("hypermedia.locus.construct", {shape:"polygon",points:[[-180,-110],[-90,-180],[70,-160],[180,-60],[160,120],[30,185],[-130,140]]});
let river = capability.invoke("hypermedia.locus.stroke_to_locus", {points:[[-30,-180],[20,-100],[-15,-20],[40,65],[10,185]],width:__width__});
let boundary = capability.invoke("hypermedia.locus.project_svg", {profile:land,fill:[72,112,77,255],padding:15});
let map = capability.invoke("hypermedia.radiance.rasterize_loci", {width:512,height:512,background:[238,231,208,255],layers:[{profile:land,fill:[100,135,91,255],matrix:[1,0,0,1,256,256]},{profile:river,fill:[55,126,158,255],matrix:[1,0,0,1,256,256]}]});
let png = capability.invoke("hypermedia.radiance.encode_rgb_png", {image:map});
let asset = {files:[{key:"catchment.png",resource:png},{key:"boundary.svg",resource:boundary}]};

requires [capability("capability.invoke")];
let tone = capability.invoke("hypermedia.acoustics.synthesize_tone", {frequency:__frequency__,sample_rate:48000,frames:48000,amplitude:__amplitude__});
let wav = capability.invoke("hypermedia.acoustics.encode_wav", {audio:tone});
let asset = {files:[{key:"tone.wav",resource:wav}]};

requires [capability("capability.invoke")];
let maps = capability.invoke("hypermedia.surface.synthesize_maps", {side:256,seed:__seed__,tint:[0.38,0.51,0.31],contrast:0.35,relief:0.003,bands:[0,0],roughness:__roughness__,metallic:0.0});
let packed = capability.invoke("hypermedia.surface.pack_pbr_set", {colour:maps.colour,normal:maps.normal,orm:maps.orm});
let asset = {files:[{key:"colour.png",resource:packed.colour},{key:"normal.png",resource:packed.normal},{key:"orm.png",resource:packed.orm}]};
